// 挑战页检测+过盾：挑战JS仅种 __sc_clearance=1(1800s) 后刷新，无计算 → 种cookie重抓即可
function hjPass(h, url){
 try{
 h=String(h==null?'':h);
 if(h.indexOf('__sc_clearance')>=0||h.indexOf('正在检查您的浏览器')>=0){
 try{cookie.setCookie(url,'__sc_clearance=1')}catch(e0){}
 try{cookie.setCookie(HJ_B,'__sc_clearance=1')}catch(e0b){}
 var h2='';
 try{h2=String(java.ajax(url))}catch(e1){}
 return h2===''?h:h2;
 }
 }catch(e){}
 return h;
}

